#include <iostream>

bool keep(int value) {
    return value % 2 == 0;
}

int main() {
    int count{0};
    for (int i{1}; i <= 5; ++i) {
        if (keep(i)) {
            ++count;
        }
    }
    std::cout << count << '\n';
}

